  "check_code": "\"\"\"Deterministic post-state checks for the Jira consolidation operation.\"\"\"\nfrom pathlib import Path\nimport hashlib\nimport json\nimport sqlite3\n\n\ndef _db(workspace):\n    return Path(workspace).parent / \"system\" / \"jira_reliability_delivery\" / \"state.db\"\n\n\ndef _row(workspace, issue_key):\n    con = sqlite3.connect(_db(workspace))\n    con.row_factory = sqlite3.Row\n    try:\n        return con.execute(\"SELECT * FROM remediation_work_items WHERE issue_key = ?\", (issue_key,)).fetchone()\n    finally:\n        con.close()\n\n\ndef _comment(row):\n    if not row:\n        return \"\"\n    try:\n        history = json.loads(row[\"status_history_json\"])\n    except (TypeError, ValueError):\n        return \"\"\n    return \" \".join(str(entry.get(\"comment\", \"\")) for entry in history).lower()\n\n\ndef check_duplicate_draft_one(workspace):\n    row = _row(workspace, \"RLY-1111\")\n    ok = bool(row and row[\"status\"] == \"Cancelled\" and row[\"duplicate_of_work_item_id\"] == \"RLY-25-097\" and \"consolidat\" in _comment(row))\n    return {\"score\": 1.0 if ok else 0.0, \"detail\": f\"RLY-1111 status={row['status'] if row else None!r}, link={row['duplicate_of_work_item_id'] if row else None!r}\"}\n\n\ndef check_duplicate_draft_two(workspace):\n    row = _row(workspace, \"RLY-1116\")\n    ok = bool(row and row[\"status\"] == \"Cancelled\" and row[\"duplicate_of_work_item_id\"] == \"RLY-25-097\" and \"consolidat\" in _comment(row))\n    return {\"score\": 1.0 if ok else 0.0, \"detail\": f\"RLY-1116 status={row['status'] if row else None!r}, link={row['duplicate_of_work_item_id'] if row else None!r}\"}\n\n\ndef check_canonical_preserved(workspace):\n    row = _row(workspace, \"RLY-1097\")\n    duplicate_one = _row(workspace, \"RLY-1111\")\n    duplicate_two = _row(workspace, \"RLY-1116\")\n    expected = {\n        \"work_item_id\": \"RLY-25-097\",\n        \"status\": \"Approved\",\n        \"summary\": \"Impose congestion-aware Traffic Manager rerouting with DNS and connection-limit health gates\",\n        \"acceptance_criteria\": \"Traffic Manager rejects a reroute when upstream DNS health is stale, connection utilization exceeds 85%, or congestion score exceeds 0.70; load validation confirms automatic rollback to the prior healthy path.\",\n        \"duplicate_of_work_item_id\": None,\n        \"updated_at\": \"2025-07-31T23:21:09Z\",\n        \"status_history_json\": '[{\"at\":\"2025-07-01T10:08:31Z\",\"from\":\"Draft\",\"to\":\"Proposed\"},{\"at\":\"2025-07-15T16:33:47Z\",\"from\":\"Proposed\",\"to\":\"Approved\"}]'\n    }\n    canonical_ok = bool(row and all(row[k] == v for k, v in expected.items()))\n    duplicates_retired = bool(\n        duplicate_one and duplicate_two\n        and duplicate_one[\"status\"] == \"Cancelled\"\n        and duplicate_two[\"status\"] == \"Cancelled\"\n    )\n    ok = canonical_ok and duplicates_retired\n    return {\"score\": 1.0 if ok else 0.0, \"detail\": f\"canonical preserved={canonical_ok}; duplicate drafts retired={duplicates_retired}\"}\n\n\ndef check_unrelated_jira_unchanged(workspace):\n    con = sqlite3.connect(_db(workspace))\n    try:\n        cols = [r[1] for r in con.execute(\"PRAGMA table_info(remediation_work_items)\")]\n        rows = []\n        for row in con.execute(\"SELECT * FROM remediation_work_items WHERE issue_key NOT IN ('RLY-1097','RLY-1111','RLY-1116') ORDER BY issue_key\"):\n            rows.append(list(row))\n        digest = hashlib.sha256(json.dumps(rows, separators=(\",\", \":\")).encode()).hexdigest()\n        expected = \"cace4d256ec4cff6c82aef0c6856d5a9b0c4bbfa5d096bc9acee80ab28890f1a\"\n        ok = len(cols) > 0 and len(rows) == 104 and digest == expected\n        return {\"score\": 1.0 if ok else 0.0, \"detail\": f\"unrelated rows={len(rows)}, digest={digest}\"}\n    finally:\n        con.close()\n",
